    test("human - freec_ratio - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] =  [ [ id:'test', single_end:false, sex:'XX' ], // meta map
                    file("${projectDir}/CNV"),
                    file("${projectDir}/ratio")
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
