process {
    withName: CONTROLFREEC_FREEC {
        ext.args = {
            [
                "sample": [
                    inputformat: 'pileup',
                    mateorientation: 'FR',
                ],
                "general": [
                    bedgraphoutput: "TRUE",
                    noisydata: "TRUE",
                    minexpectedgc: "0",
                    readcountthreshold: "1",
                    sex: meta.sex,
                    window: "10",
                ],
                "control": [
                    inputformat: "pileup",
                    mateorientation: "FR",
                ],
            ]
        }
    }
